use alloc::collections::{btree_map, BTreeMap};
use alloc::vec::Vec;

#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
pub struct IndexSet<T> {
    key2slot: BTreeMap<T, SlotIndex>,
    slots: Vec<T>,
}

impl<T> IndexSet<T>
where
    T: Ord + Clone,
{
    pub fn new() -> Self {
        Self {
            key2slot: BTreeMap::new(),
            slots: Vec::new(),
        }
    }

    // ... other existing methods omitted for brevity ...

    pub fn remove(&mut self, value: T) -> bool {
        if let Some(slot_index) = self.key2slot.remove(&value) {
            let index = slot_index.index();
            let last = self.slots.len() - 1;
            self.slots.swap_remove(index);
            if index != last {
                let moved = self.slots[index].clone();
                self.key2slot.insert(moved, SlotIndex(index));
            }
            true
        } else {
            false
        }
    }
}",
