{
  "title": "Export table to JSON file",
  "description": "A user wants to export the contents of a table to a JSON file for backup or migration. The helper writes a pretty‑printed JSON array of row objects.",
  "code_context": "use std::{fs::File, path::Path};
use gluesql_core::{error::Result, store::Store};

impl JsonStorage {
    pub async fn export_table<P: AsRef<std::path::Path>>(&self, table_name: &str, out_path: P) -> Result<()> {
        let rows_iter = self.scan_data(table_name).await?;
        let schema = self.fetch_schema(table_name).await?.ok_or_else(|| {
            gluesql_core::error::Error::StorageMsg(format!("Table {} does not exist", table_name))
        })?;
        let jsons: Vec<serde_json::Value> = rows_iter
            .map(|res| {
                let (_key, row) = res?;
                match row {
                    gluesql_core::data::DataRow::Vec(values) => {
                        let labels = schema
                            .column_defs
                            .as_ref()
                            .map(|defs| defs.iter().map(|c| c.name.clone()).collect::<Vec<_>>())
                            .unwrap_or_default();
                        let obj = serde_json::Map::from_iter(
                            labels
                                .into_iter()
                                .zip(values.into_iter())
                                .map(|(k, v)| Ok((k, v.try_into()?)))
                        );
                        Ok(serde_json::Value::Object(obj))
                    }
                    gluesql_core::data::DataRow::Map(map) => {
                        let obj = serde_json::Map::from_iter(
                            map.into_iter()
                                .map(|(k, v)| Ok((k, v.try_into()?)))
                        );
                        Ok(serde_json::Value::Object(obj))
                    }
                }
            })
            .collect::<Result<Vec<_>>>()?;
        let out_file = std::fs::File::create(out_path).map_err(|e| {
            gluesql_core::error::Error::StorageMsg(e.to_string())
        })?;
        serde_json::to_writer_pretty(out_file, &jsons).map_err(|e| {
            gluesql_core::error::Error::StorageMsg(e.to_string())
        })?;
        Ok(())
    }
}",
  "function_signature": "fn export_table<P: AsRef<std::path::Path>>(&self, table_name: &str, out_path: P) -> Result<()>"
}

