  "description": "A developer is building a Grafbase service that needs to track the performance of GraphQL operations with detailed context. They want to record the duration of a GraphQL operation in metrics, including the client name and version, the operation name, and the operation type. The existing `EngineMetrics::record_query_or_mutation_duration` function already supports recording duration and status, but it lacks the ability to capture the operation name and client details in a structured way. This helper combines the operation's attributes and client information into a single, reusable call that ensures all relevant telemetry is captured consistently across the application.",
  "code_context": "use opentelemetry::KeyValue;
use crate::{
    grafbase_client::Client,
    graphql::{GraphqlOperationAttributes, GraphqlResponseStatus},
    metrics::engine::EngineMetrics,
};

impl EngineMetrics {
    fn create_operation_key_values(&self, operation: GraphqlOperationAttributes) -> Vec<KeyValue> {
        let mut attributes = vec![
            KeyValue::new("graphql.document", operation.sanitized_query.clone()),
            KeyValue::new("graphql.operation.type", operation.ty.as_str()),
        ];

        match operation.name {
            crate::graphql::OperationName::Original(name) => {
                attributes.push(KeyValue::new("graphql.operation.name", name));
            }
            crate::graphql::OperationName::Computed(name) => {
                attributes.push(KeyValue::new("grafbase.operation.computed_name", name));
            }
            crate::graphql::OperationName::Unknown => (),
        }

        attributes
    }

    pub fn record_query_or_mutation_duration(
        &self,
        GraphqlRequestMetricsAttributes {
            operation,
            status,
            client,
        }: GraphqlRequestMetricsAttributes,
        latency: std::time::Duration,
    ) {
        if operation.ty.is_subscription() {
            return;
        }
        let mut attributes = self.create_operation_key_values(operation);

        if let Some(version) = self.graph_version.clone() {
            attributes.push(KeyValue::new("grafbase.graph.version", version));
        }

        attributes.push(KeyValue::new("graphql.response.status", status.as_str()));

        if let Some(client) = client {
            attributes.push(KeyValue::new("http.headers.x-grafbase-client-name", client.name));

            if let Some(version) = client.version {
                attributes.push(KeyValue::new("http.headers.x-grafbase-client-version", version));
            }
        }

        self.operation_latency.record(latency.as_millis() as u64, &attributes);
    }
}",
