    let base_path = std::path::Path::new(requesting_file).parent().ok_or("Invalid requesting file path")?;
    let include_path = match include_type {
        IncludeType::Relative => base_path.join(name),
        IncludeType::Standard => std::env::var("SHADER_INCLUDE_PATH")
