  "code_context": "use deno_core::{JsRuntime, error::AnyError};
use deno_core::serde_v8;

pub struct FetchOptions {
    pub method: String,
    pub cache: bool,
    pub timeout: u32,
}

impl Default for FetchOptions {
    fn default() -> Self {
        Self {
            method: "GET".to_string(),
            cache: false,
            timeout: 30_000,
        }
    }
}

pub fn fetch_options_converter(runtime: &mut JsRuntime) -> impl Fn(&str) -> Result<FetchOptions, AnyError> {
    let init_script = r#"
        const converter = createDictionaryConverter(
            "FetchOptions",
            [
                { key: "method", converter: converters.DOMString, defaultValue: "GET" },
                { key: "cache", converter: converters.boolean, defaultValue: false },
                { key: "timeout", converter: converters["unsigned long"], defaultValue: 30000 },
            ]
        );
        globalThis.__fetchOptionsConverter = converter;
    "#;
    runtime.execute_script("init_fetch_options", init_script).unwrap();
    move |json_str: &str| {
        let parse_script = format!("JSON.parse({})", json_str);
        let js_val = runtime.execute_script("parse_fetch_options", &parse_script)?;
        let conv_script = "__fetchOptionsConverter";
        let converter = runtime.execute_script("get_converter", conv_script)?;
        let scope = &mut runtime.handle_scope();
        let args = [js_val.open(scope)];
        let result = deno_core::v8::Function::new(scope, converter.open(scope).into()).unwrap().call(scope, converter.open(scope).into(), &args);
        let obj = result.ok_or_else(|| deno_core::error::generic_error("Conversion failed"))?;
        let opts: FetchOptions = serde_v8::from_v8(scope, obj)?;
        Ok(opts)
    }
}",
