  "description": "I am building a high‑throughput indexer that processes thousands of transactions per second. I need to insert or update a batch of objects in a single database transaction. The existing `put_object` method only handles one object at a time, leading to a significant performance penalty due to repeated database round‑trips. I need a new function that accepts a `Vec<(i64, Vec<FtColumn>, Vec<u8>)>` and performs a single `INSERT … ON CONFLICT DO UPDATE` for all items. The function must use a single database connection and transaction, handle errors gracefully (e.g., if one item fails, the entire batch should be rolled back), and return the number of items successfully processed.",
  "code_context": "use crate::{IndexerError, IndexerResult};
use fuel_indexer_database::queries;
use fuel_indexer_lib::utils::format_sql_query;
use std::collections::HashMap;

impl Database {
    pub async fn batch_put_objects(
        &mut self,
        objects: Vec<(i64, Vec<FtColumn>, Vec<u8>)>,
    ) -> IndexerResult<usize> {
        self.start_transaction().await?;
        let mut success_count = 0;
        for (type_id, columns, bytes) in objects {
            let table = self.tables.get(&type_id).ok_or_else(|| {
                IndexerError::DatabaseError(IndexerDatabaseError::TableMappingDoesNotExist(type_id))
            })?;
            let inserts: Vec<String> = columns.iter().map(|c| c.query_fragment()).collect();
            let updates: Vec<String> = self.schema[table]
                .iter()
                .zip(columns.iter())
                .map(|(col_name, value)| format!("{} = {}", col_name, value.query_fragment()))
                .collect();
            let query_text = self.upsert_query(table, &self.schema[table], inserts, updates);
            let conn = self.stashed.as_mut().ok_or_else(||
                IndexerError::NoTransactionError("batch_put_objects".to_string())
            )?;
            if let Err(e) = queries::put_object(conn, query_text, bytes).await {
                self.revert_transaction().await?;
                return Err(e);
            }
            success_count += 1;
        }
        self.commit_transaction().await?;
        Ok(success_count)
    }
}",
