fn read_binary<R: std::io::Read, D: std::fmt::Debug>(
    entry: &mut R,
    binary_path: D,
) -> Result<(Vec<u8>, &'static str)> {
    let mut binary_data = Vec::new();
    entry
        .read_to_end(&mut binary_data)
        .into_diagnostic()
        .wrap_err_with(|| format!("failed to read binary `{:?}`", binary_path))?;
    let object = object::File::parse(&*binary_data)
        .into_diagnostic()
        .wrap_err("invalid object file")?;
    let arch = match object.architecture() {
        object::Architecture::Aarch64 => "arm64",
        object::Architecture::X86_64 => "x86_64",
        other => return Err(BuildError::InvalidBinaryArchitecture(other).into()),
    };
    Ok((binary_data, arch))
}

