  "title": "Generate a random block header for testing",
  "description": "A developer needs to generate a random block header for testing purposes, including valid base16 encoded fields and proper serialization/deserialization behavior while ensuring the header's id is computed correctly.",
  "code_context": "use crate::{Header, AutolykosSolution, Votes, BlockId, Digest32, ADDigest, blake2b256_hash};
use crate::ec_point::EcPoint;
use num_bigint::BigInt;
use sigma_ser::ScorexSerializationError;
use sigma_ser::vlq_encode::{WriteSigmaVlqExt, ReadSigmaVlqExt};
use byteorder::{BigEndian, WriteBytesExt, ReadBytesExt};

impl Header {
    pub fn serialize_without_pow(&self) -> Result<Vec<u8>, ScorexSerializationError> {
        let mut data = Vec::new();
        let mut w = &mut data;
        w.put_u8(self.version)?;
        self.parent_id.0.scorex_serialize(&mut w)?;
        self.ad_proofs_root.scorex_serialize(&mut w)?;
        self.transaction_root.scorex_serialize(&mut w)?;
        self.state_root.scorex_serialize(&mut w)?;
        w.put_u64(self.timestamp)?;
        self.extension_root.scorex_serialize(&mut w)?;
        let mut n_bits_writer = vec![];
        n_bits_writer.write_u32::<BigEndian>(self.n_bits as u32).unwrap();
        w.write_all(&n_bits_writer)?;
        w.put_u32(self.height)?;
        w.write_all(&self.votes.0)?;
        if self.version > 1 { w.put_i8(0)?; }
        Ok(data)
    }
}

impl AutolykosSolution {
    pub fn serialize_bytes<W: WriteSigmaVlqExt>(&self, version: u8, w: &mut W) -> Result<(), sigma_ser::ScorexSerializationError> {
        if version == 1 {
            self.miner_pk.scorex_serialize(w)?;
            self.pow_onetime_pk.as_ref().ok_or(sigma_ser::ScorexSerializationError::Misc("pow_onetime_pk must == Some(_) for autolykos v1"))?.scorex_serialize(w)?;
            w.write_all(&self.nonce)?;
            let d_bytes = self.pow_distance.as_ref().ok_or(sigma_ser::ScorexSerializationError::Misc("pow_distance must be == Some(_) for autolykos v1"))?.to_signed_bytes_be();
            w.put_u8(d_bytes.len() as u8)?;
            w.write_all(&d_bytes)?;
        } else {
            self.miner_pk.scorex_serialize(w)?;
            w.write_all(&self.nonce)?;
        }
        Ok(())
    }
}",
