  "title": "Convert Ini to JSON-like structure",
  "description": "A developer wants to export an INI configuration to a JSON-like structure where sections become keys and their key-value pairs become nested objects. This is needed for integration with web applications or tools that expect JSON-formatted configuration. The user needs a helper function that converts an Ini instance into a nested HashMap structure that can be serialized to JSON.",
  "code_context": "use std::collections::HashMap;
use std::fmt;
use crate::ordered_hashmap::OrderedHashMap;

pub struct Ini {
    document: OrderedHashMap<String, Section>,
    last_section_name: String,
    empty_section: Section,
}

pub struct Section {
    inner: OrderedHashMap<String, String>,
}

impl Section {
    pub fn new() -> Self {
        Section { inner: OrderedHashMap::new() }
    }
    pub fn iter(&self) -> ordered_hashmap::Iter<'_, String, String> {
        self.inner.iter()
    }
}

impl Ini {
    pub fn new() -> Ini {
        Ini { document: OrderedHashMap::new(), last_section_name: String::new(), empty_section: Section::new() }
    }
    pub fn section<S>(mut self, name: S) -> Self
    where
        S: Into<String>,
    {
        self.last_section_name = name.into();
        self
    }
    pub fn item<N, V>(mut self, name: N, value: V) -> Self
    where
        N: Into<String>,
        V: fmt::Display,
    {
        self.document
            .entry(self.last_section_name.clone())
            .or_insert_with(Section::new)
            .inner
            .insert(name.into(), value.to_string());
        self
    }
    pub fn iter(&self) -> ordered_hashmap::Iter<'_, String, Section> {
        self.document.iter()
    }
}",
